using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Http.HttpResults;
using ProductApi.Models;
using ProductApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();
builder.Services.AddOpenApi();
builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter());
});

var app = builder.Build();

app.MapOpenApi();

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService svc) => svc.GetAll())
    .WithName("GetAllProducts")
    .WithSummary("List all products")
    .WithDescription("Returns the complete list of products currently stored in memory.")
    .Produces<IReadOnlyList<Product>>(StatusCodes.Status200OK);

products.MapGet("/{id:int}", Results<Ok<Product>, NotFound> (int id, IProductService svc) =>
    {
        var product = svc.GetById(id);
        return product is not null
            ? TypedResults.Ok(product)
            : TypedResults.NotFound();
    })
    .WithName("GetProductById")
    .WithSummary("Get a product by ID")
    .WithDescription("Returns a single product matching the given ID, or 404 if not found.")
    .Produces<Product>(StatusCodes.Status200OK)
    .Produces(StatusCodes.Status404NotFound);

products.MapPost("/", Results<Created<Product>, ValidationProblem> (CreateProductRequest request, IProductService svc) =>
    {
        if (string.IsNullOrWhiteSpace(request.Name))
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["Name"] = ["Product name is required."]
            });
        }

        if (request.Price < 0)
        {
            return TypedResults.ValidationProblem(new Dictionary<string, string[]>
            {
                ["Price"] = ["Price must not be negative."]
            });
        }

        var product = svc.Create(request);
        return TypedResults.Created($"/api/products/{product.Id}", product);
    })
    .WithName("CreateProduct")
    .WithSummary("Create a new product")
    .WithDescription("Creates a product with the supplied name, price, and category. Returns the created product with its assigned ID and timestamp.")
    .Produces<Product>(StatusCodes.Status201Created)
    .ProducesValidationProblem();

app.Run();

